解锁所有图层.code:
#target photoshop
(function unlockAllLayers() {
    if (app.documents.length === 0) return;
    var d = app.activeDocument;
    function doUnlock() {
        try {
            if (d.backgroundLayer) d.backgroundLayer.isBackgroundLayer = false;
        } catch (e) {}
        var ts = 0;
        try {
            var r2 = new ActionReference();
            r2.putProperty(charIDToTypeID('Prpr'), stringIDToTypeID('numberOfLayers'));
            r2.putEnumerated(charIDToTypeID('Dcmn'), charIDToTypeID('Ordn'), charIDToTypeID('Trgt'));
            ts = executeActionGet(r2).getInteger(stringIDToTypeID('numberOfLayers'));
        } catch (e) { return; }
        for (var j = 1; j <= ts; j++) {
            try {
                var r3 = new ActionReference();
                r3.putIndex(charIDToTypeID('Lyr '), j);
                var ld = executeActionGet(r3);
                if (typeIDToStringID(ld.getEnumerationValue(stringIDToTypeID('layerSection'))) !== 'layerSectionEnd' && ld.hasKey(stringIDToTypeID('layerLocking'))) {
                    var lk = ld.getObjectValue(stringIDToTypeID('layerLocking'));
                    var d2 = new ActionDescriptor();
                    var rf = new ActionReference();
                    rf.putIdentifier(charIDToTypeID('Lyr '), ld.getInteger(stringIDToTypeID('layerID')));
                    d2.putReference(charIDToTypeID('null'), rf);
                    var lp = new ActionDescriptor();
                    var ks = ['protectAll', 'protectComposite', 'protectPosition', 'protectTrans', 'protectArtboardAutonest'];
                    var sh = false;
                    for (var k = 0; k < ks.length; k++) {
                        var kid = stringIDToTypeID(ks[k]);
                        if (lk.hasKey(kid) && lk.getBoolean(kid) === true) {
                            lp.putBoolean(kid, false);
                            sh = true;
                        }
                    }
                    if (sh) {
                        d2.putObject(charIDToTypeID('T   '), stringIDToTypeID('layerLocking'), lp);
                        executeAction(charIDToTypeID('setd'), d2, DialogModes.NO);
                    }
                }
            } catch (e) {}
        }
    }
    d.suspendHistory('解锁所有图层', 'doUnlock()');
})();

新建参考线.code:
#target photoshop

(function openGuideLayoutAndAutoLock() {
    // 1. 检查是否有处于打开状态的文档
    if (app.documents.length === 0) {
        alert("请先在 Photoshop 中打开一个文档。");
        return;
    }

    var idNewGuideLayout = stringIDToTypeID("newGuideLayout");
    var SETTINGS_KEY = "AutoSavedGuideLayoutSettings";
    var desc;

    // 2. 读取上次记住的设置（避免恢复成默认 8 栏）
    try {
        desc = app.getCustomOptions(SETTINGS_KEY);
    } catch (e) {
        desc = new ActionDescriptor();
    }

    // 3. 打开“新建参考线版面”弹窗
    try {
        var resultDesc = executeAction(idNewGuideLayout, desc, DialogModes.ALL);

        // 4. 用户点击“确定”后：先记住新参数，随后立即锁定参考线
        if (resultDesc) {
            app.putCustomOptions(SETTINGS_KEY, resultDesc, true);
            lockAllGuides();
        }
    } catch (e) {
        // 用户主动点击“取消”时静默退出
        if (e.number !== 8007) {
            alert("操作失败：" + e.message);
        }
    }

    /**
     * 锁定参考线（等同于勾选菜单栏：视图 -> 锁定参考线）
     */
    function lockAllGuides() {
        try {
            var descSet = new ActionDescriptor();
            var ref = new ActionReference();

            ref.putProperty(charIDToTypeID("Prpr"), stringIDToTypeID("guidesLocked"));
            ref.putEnumerated(charIDToTypeID("capp"), charIDToTypeID("Ordn"), charIDToTypeID("Trgt"));
            descSet.putReference(charIDToTypeID("null"), ref);

            var descPref = new ActionDescriptor();
            // 直接设为 true（锁定状态），即使原本已锁定也不会被意外反转解锁
            descPref.putBoolean(stringIDToTypeID("guidesLocked"), true);
            descSet.putObject(charIDToTypeID("T   "), stringIDToTypeID("guidePreferences"), descPref);

            executeAction(charIDToTypeID("setd"), descSet, DialogModes.NO);
        } catch (err) {
            // 锁定异常时静默忽略，不干扰正常生成的线
        }
    }
})();

批量修改文字样式.code:
#target photoshop
app.bringToFront();

/*
 * 文字样式智能定制器 Pro（强化版）
 * 相对原版的改动：
 *   1. 图层识别改为 DOM 索引 + 四级降级链 + 图层组穿透，并在失败时告知「你选中的到底是什么」
 *   2. 字体只写 fontPostScriptName（原版把 PS 名写进 fontName 字族名，会导致字族继承错乱）
 *   3. stylesExactMatch 补 default 分支，复杂类型不再被误判为「相同」而合并丢属性
 *   4. 样式应用改为按「原始样式段边界」分段处理，长文本从 O(n²) 降到 O(n)
 *   5. 颜色输入自动规范化；非法 HEX 会明确提示而不是静默跳过
 *   6. 还原多选选中状态放进 finally，中途报错也不丢原选区
 *   7. 拾色器改用 ActionManager 原生拾色通道，可在画布/屏幕任意取色且不死锁
 *   8. CID() 强制校验 charID 必须是 4 字符，杜绝「少打一个空格」这类隐性故障
 */
(function () {
    try {
        if (app.documents.length === 0) {
            alert("请先在 Photoshop 中打开包含文字图层的文档。");
            return;
        }

        var doc = app.activeDocument;

        try {
            executeAction(stringIDToTypeID("commitTextTool"), new ActionDescriptor(), DialogModes.NO);
        } catch (eCommit) {}

        /* ==================== CORE-BEGIN ====================
         * 本区块内全部为无外部依赖的纯函数（只依赖入参），可被独立提取做无头测试。
         * ================================================== */

        // charID 必须是 4 个字符；写错长度时立刻报错，而不是留到运行时变成「非法参数」
        function CID(s) {
            if (s.length !== 4) throw new Error("charID 必须是 4 个字符，收到 '" + s + "' (" + s.length + " 个)");
            return charIDToTypeID(s);
        }

        function duplicateDesc(src) {
            if (!src) return new ActionDescriptor();
            var dst = new ActionDescriptor();
            for (var i = 0; i < src.count; i++) {
                var key = src.getKey(i);
                var type = src.getType(key);
                switch (type) {
                    case DescValueType.BOOLEANTYPE: dst.putBoolean(key, src.getBoolean(key)); break;
                    case DescValueType.INTEGERTYPE: dst.putInteger(key, src.getInteger(key)); break;
                    case DescValueType.DOUBLETYPE: dst.putDouble(key, src.getDouble(key)); break;
                    case DescValueType.STRINGTYPE: dst.putString(key, src.getString(key)); break;
                    case DescValueType.UNITDOUBLE: dst.putUnitDouble(key, src.getUnitDoubleType(key), src.getUnitDoubleValue(key)); break;
                    case DescValueType.OBJECTTYPE: dst.putObject(key, src.getObjectType(key), duplicateDesc(src.getObjectValue(key))); break;
                    case DescValueType.LISTTYPE: dst.putList(key, src.getList(key)); break;
                    case DescValueType.ENUMERATEDTYPE: dst.putEnumerated(key, src.getEnumerationType(key), src.getEnumerationValue(key)); break;
                    case DescValueType.REFERENCETYPE: dst.putReference(key, src.getReference(key)); break;
                    case DescValueType.ALIASTYPE: dst.putPath(key, src.getPath(key)); break;
                    case DescValueType.CLASSTYPE: dst.putClass(key, src.getClass(key)); break;
                }
            }
            return dst;
        }

        // 全属性严格比对：行距/语言/消除锯齿/缩放等未被勾选的项绝不能被合并掉
        function stylesExactMatch(d1, d2) {
            if (!d1 && !d2) return true;
            if (!d1 || !d2) return false;
            if (d1.count !== d2.count) return false;

            for (var i = 0; i < d1.count; i++) {
                var key = d1.getKey(i);
                if (!d2.hasKey(key)) return false;
                var t1 = d1.getType(key);
                var t2 = d2.getType(key);
                if (t1 !== t2) return false;

                switch (t1) {
                    case DescValueType.BOOLEANTYPE:
                        if (d1.getBoolean(key) !== d2.getBoolean(key)) return false;
                        break;
                    case DescValueType.INTEGERTYPE:
                        if (d1.getInteger(key) !== d2.getInteger(key)) return false;
                        break;
                    case DescValueType.DOUBLETYPE:
                        if (Math.abs(d1.getDouble(key) - d2.getDouble(key)) > 0.0001) return false;
                        break;
                    case DescValueType.STRINGTYPE:
                        if (d1.getString(key) !== d2.getString(key)) return false;
                        break;
                    case DescValueType.UNITDOUBLE:
                        if (d1.getUnitDoubleType(key) !== d2.getUnitDoubleType(key)) return false;
                        if (Math.abs(d1.getUnitDoubleValue(key) - d2.getUnitDoubleValue(key)) > 0.0001) return false;
                        break;
                    case DescValueType.ENUMERATEDTYPE:
                        if (d1.getEnumerationType(key) !== d2.getEnumerationType(key) ||
                            d1.getEnumerationValue(key) !== d2.getEnumerationValue(key)) return false;
                        break;
                    case DescValueType.OBJECTTYPE:
                        if (key === CID("Clr ")) {
                            var c1 = d1.getObjectValue(key);
                            var c2 = d2.getObjectValue(key);
                            if (Math.abs(c1.getDouble(CID("Rd  ")) - c2.getDouble(CID("Rd  "))) > 0.1 ||
                                Math.abs(c1.getDouble(CID("Grn ")) - c2.getDouble(CID("Grn "))) > 0.1 ||
                                Math.abs(c1.getDouble(CID("Bl  ")) - c2.getDouble(CID("Bl  "))) > 0.1) return false;
                        } else {
                            if (!stylesExactMatch(d1.getObjectValue(key), d2.getObjectValue(key))) return false;
                        }
                        break;
                    default:
                        // 无法平级比较的类型（引用/类对象等）保守视为不同，宁可多切一段也不丢属性
                        return false;
                }
            }
            return true;
        }

        function hexToRgb(hex) {
            if (!hex) return null;
            hex = String(hex).replace(/^#/, "");
            if (hex.length === 3) hex = hex.charAt(0) + hex.charAt(0) + hex.charAt(1) + hex.charAt(1) + hex.charAt(2) + hex.charAt(2);
            if (hex.length !== 6) return null;
            if (!/^[0-9a-fA-F]{6}$/.test(hex)) return null;
            var r = parseInt(hex.substring(0, 2), 16);
            var g = parseInt(hex.substring(2, 4), 16);
            var b = parseInt(hex.substring(4, 6), 16);
            return [r, g, b];
        }

        function rgbToHex(r, g, b) {
            function pad(v) {
                var h = Math.round(v).toString(16);
                return h.length === 1 ? "0" + h : h;
            }
            return ("#" + pad(r) + pad(g) + pad(b)).toUpperCase();
        }

        // 用户可能输入 ff0000 / #ff0000 / 带空格；统一成 #RRGGBB（最多 7 位）
        function normalizeHex(h) {
            var s = String(h === undefined || h === null ? "" : h).replace(/\s/g, "").replace(/^#+/, "").toUpperCase();
            if (/^[0-9A-F]{3}$/.test(s)) s = s.charAt(0) + s.charAt(0) + s.charAt(1) + s.charAt(1) + s.charAt(2) + s.charAt(2);
            if (!/^[0-9A-F]{6}$/.test(s)) return null;
            return "#" + s;
        }

        function selectSingleLayerById(layerId) {
            var desc = new ActionDescriptor();
            var ref = new ActionReference();
            ref.putIdentifier(CID("Lyr "), layerId);
            desc.putReference(CID("null"), ref);
            desc.putBoolean(CID("MkVs"), false);
            executeAction(CID("slct"), desc, DialogModes.NO);
        }

        // ---------- 用 DOM 递归建立「图层 id -> 节点」索引 ----------
        // DOM 的 l.id / layerSets / layers 在任何 PS 版本下都稳定，不依赖 ActionManager 的索引偏移
        function buildLayerIndex(container, out) {
            out = out || {};
            var list = null;
            try { list = container.layers; } catch (eL) { return out; }
            if (!list) return out;
            for (var i = 0; i < list.length; i++) {
                var l = list[i];
                var isSet = false;
                var isText = false;
                var locked = false;
                try { isSet = (l.typename === "LayerSet"); } catch (e1) {}
                if (!isSet) { try { isText = (l.kind === LayerKind.TEXT); } catch (e2) {} }
                try { locked = !!l.allLocked; } catch (e3) {}
                out[l.id] = { id: l.id, name: l.name, isSet: isSet, isText: isText, locked: locked, dom: l };
                if (isSet) buildLayerIndex(l, out);
            }
            return out;
        }

        // 递归收集文字图层节点（含任意层级的嵌套组），按 DOM 顺序
        function collectTextNodesDeep(container, acc, seen) {
            acc = acc || [];
            seen = seen || {};
            var list = null;
            try { list = container.layers; } catch (eL) { return acc; }
            if (!list) return acc;
            for (var i = 0; i < list.length; i++) {
                var l = list[i];
                var isSet = false;
                try { isSet = (l.typename === "LayerSet"); } catch (e1) {}
                if (isSet) {
                    collectTextNodesDeep(l, acc, seen);
                } else {
                    var isText = false;
                    try { isText = (l.kind === LayerKind.TEXT); } catch (e2) {}
                    if (isText && !seen[l.id]) {
                        seen[l.id] = true;
                        var locked = false;
                        try { locked = !!l.allLocked; } catch (e3) {}
                        acc.push({ id: l.id, name: l.name, isSet: false, isText: true, locked: locked, dom: l });
                    }
                }
            }
            return acc;
        }

        // ---------- 选中图层的四级降级识别 + 图层组穿透 ----------
        // 返回 { layers: 可处理文字层, allText: 文档全部文字层, rejected: 被跳过的选中项说明 }
        function resolveTargetLayers(container) {
            var index = buildLayerIndex(container, {});
            var allText = collectTextNodesDeep(container, [], {});

            // 1) 多选：targetLayersIDs
            var candIds = [];
            try {
                var ref = new ActionReference();
                ref.putProperty(CID("Prpr"), stringIDToTypeID("targetLayersIDs"));
                ref.putEnumerated(CID("Dcmn"), CID("Ordn"), CID("Trgt"));
                var d = executeActionGet(ref);
                if (d.hasKey(stringIDToTypeID("targetLayersIDs"))) {
                    var list = d.getList(stringIDToTypeID("targetLayersIDs"));
                    for (var i = 0; i < list.count; i++) {
                        try { candIds.push(list.getReference(i).getIdentifier()); } catch (e1) {}
                    }
                }
            } catch (eA) {}

            // 2) 单选：目标图层的 LyrI 属性
            if (candIds.length === 0) {
                try {
                    var r2 = new ActionReference();
                    r2.putProperty(CID("Prpr"), CID("LyrI"));
                    r2.putEnumerated(CID("Lyr "), CID("Ordn"), CID("Trgt"));
                    candIds.push(executeActionGet(r2).getInteger(CID("LyrI")));
                } catch (eB) {}
            }

            // 3) DOM activeLayer
            if (candIds.length === 0) {
                try { candIds.push(container.activeLayer.id); } catch (eC) {}
            }

            var result = [];
            var seen = {};
            var rejected = [];

            function pushNode(node) {
                if (!node || seen[node.id]) return;
                seen[node.id] = true;
                result.push({ id: node.id, name: node.name });
            }

            for (var k = 0; k < candIds.length; k++) {
                var node = index[candIds[k]];
                if (!node) {
                    rejected.push("id " + candIds[k] + "（不在图层索引中，可能是图层组内部目标）");
                    continue;
                }
                if (node.isSet) {
                    var subs = collectTextNodesDeep(node.dom, [], {});
                    for (var s = 0; s < subs.length; s++) pushNode(subs[s]);
                    if (subs.length === 0) rejected.push("图层组「" + node.name + "」内没有文字图层");
                } else if (node.isText) {
                    if (node.locked) rejected.push("文字图层「" + node.name + "」已锁定");
                    else pushNode(node);
                } else {
                    rejected.push("「" + node.name + "」不是文字图层");
                }
            }

            // 4) 兜底：当前活动图层
            if (result.length === 0) {
                try {
                    var al = container.activeLayer;
                    var alNode = index[al.id];
                    if (alNode) {
                        if (alNode.isSet) {
                            var subs2 = collectTextNodesDeep(alNode.dom, [], {});
                            for (var s2 = 0; s2 < subs2.length; s2++) pushNode(subs2[s2]);
                        } else if (alNode.isText && !alNode.locked) {
                            pushNode(alNode);
                        }
                    }
                } catch (eD) {}
            }

            return { layers: result, allText: allText, rejected: rejected };
        }

        // ---------- 取文字描述符（用属性式引用，避开裸引用的兼容性差异）----------
        function readTextDescById(layerId) {
            var ref = new ActionReference();
            ref.putProperty(CID("Prpr"), stringIDToTypeID("textKey"));
            ref.putIdentifier(CID("Lyr "), layerId);
            var d = executeActionGet(ref);
            if (!d.hasKey(stringIDToTypeID("textKey"))) return null;
            return d.getObjectValue(stringIDToTypeID("textKey"));
        }

        // ---------- 应用样式：按「原始样式段边界」分段，O(n) ----------
        // cfg: {
        //   regex, sizeUnit,
        //   matchEnabled, matchFont, matchSize, matchShift, matchTrack, matchColor,
        //   baseEnabled, baseFont, baseSize, baseColor
        // }
        function applyTextStyles(layerId, cfg) {
            selectSingleLayerById(layerId);

            var textDesc = readTextDescById(layerId);
            if (!textDesc) return false;

            var rawText = "";
            try { rawText = textDesc.getString(CID("Txt ")); } catch (eTxt) { return false; }
            var total = rawText.length;
            if (total === 0) return false;

            // --- 匹配掩码 ---
            var isMatch = [];
            for (var i = 0; i < total; i++) isMatch[i] = false;
            var re = cfg.regex;
            re.lastIndex = 0;
            var m;
            while ((m = re.exec(rawText)) !== null) {
                if (m[0].length === 0) { re.lastIndex++; continue; }
                var endIdx = m.index + m[0].length;
                for (var p = m.index; p < endIdx && p < total; p++) isMatch[p] = true;
            }

            // --- 原始样式按字符展开，同时记录所属原始段号（分段键）---
            var charStyle = [];
            var charGroup = [];
            var fallbackStyle = null;

            var rangesList = null;
            var hasRanges = false;
            if (textDesc.hasKey(stringIDToTypeID("textStyleRange"))) {
                rangesList = textDesc.getList(stringIDToTypeID("textStyleRange"));
                hasRanges = (rangesList && rangesList.count > 0);
            }

            if (hasRanges) {
                fallbackStyle = rangesList.getObjectValue(0).getObjectValue(stringIDToTypeID("textStyle"));
                for (var r = 0; r < rangesList.count; r++) {
                    var ro = rangesList.getObjectValue(r);
                    var rf = ro.hasKey(stringIDToTypeID("from")) ? ro.getInteger(stringIDToTypeID("from")) : 0;
                    var rt = ro.hasKey(stringIDToTypeID("to")) ? ro.getInteger(stringIDToTypeID("to")) : total;
                    if (rf < 0) rf = 0;
                    if (rt > total) rt = total;
                    var st = ro.getObjectValue(stringIDToTypeID("textStyle"));
                    for (var ci = rf; ci < rt; ci++) { charStyle[ci] = st; charGroup[ci] = r; }
                }
            } else if (textDesc.hasKey(stringIDToTypeID("defaultStyle"))) {
                fallbackStyle = textDesc.getObjectValue(stringIDToTypeID("defaultStyle"));
            }
            for (var cf = 0; cf < total; cf++) {
                if (charStyle[cf] === undefined) { charStyle[cf] = fallbackStyle; charGroup[cf] = -1; }
            }

            // --- 分段并套用样式 ---
            var outRanges = [];
            var activeStyle = null;
            var activeFrom = 0;

            function buildSegmentStyle(from, segMatch) {
                var style = duplicateDesc(charStyle[from]);
                if (segMatch) {
                    if (!cfg.matchEnabled) return style;
                    if (cfg.matchFont) {
                        // 只写 PostScript 名。fontName 是字族显示名，写 PS 名会让字族继承错乱
                        style.putString(stringIDToTypeID("fontPostScriptName"), cfg.matchFont);
                    }
                    if (cfg.matchSize !== null && cfg.matchSize > 0) {
