                var picked = pickColorWithNativeDialog(null);
                if (picked) {
                    if (doPickTarget) { targetConfig.hex = picked; targetConfig.colorEnabled = true; }
                    if (doPickBase) { baseConfig.hex = picked; baseConfig.colorEnabled = true; }
                }
                continue;
            } else if (res === 1) {
                saveCurrentState();
                break;
            } else {
                return;
            }
        }

        // ==================== 解析配置 ====================
        var regString = (presetIdx < 5) ? presetRegexMap[presetIdx] : customRegex;
        var userRegex = null;
        try {
            userRegex = new RegExp(regString, "g");
        } catch (eRe) {
            alert("正则表达式有误，请检查！\n错误信息: " + eRe.message);
            return;
        }

        var cfg = {
            regex: userRegex,
            sizeUnit: baseSizeUnit,
            matchEnabled: targetConfig.enabled,
            matchFont: null, matchSize: null, matchShift: null, matchTrack: null, matchColor: null,
            baseEnabled: baseConfig.enabled,
            baseFont: null, baseSize: null, baseColor: null
        };

        if (targetConfig.enabled) {
            if (targetConfig.fontEnabled) {
                cfg.matchFont = fontTree[targetConfig.catIdx].families[targetConfig.famIdx].styles[targetConfig.wgtIdx].ps;
            }
            if (targetConfig.sizeEnabled) {
                cfg.matchSize = parseFloat(targetConfig.sizeVal);
                if (isNaN(cfg.matchSize) || cfg.matchSize <= 0) {
                    alert("目标字号无效：" + targetConfig.sizeVal);
                    return;
                }
            }
            if (targetConfig.shiftEnabled) {
                cfg.matchShift = parseFloat(targetConfig.shiftVal);
                if (isNaN(cfg.matchShift)) { alert("基线偏移无效：" + targetConfig.shiftVal); return; }
            }
            if (targetConfig.trackEnabled) {
                cfg.matchTrack = parseInt(targetConfig.trackVal, 10);
                if (isNaN(cfg.matchTrack)) { alert("字距无效：" + targetConfig.trackVal); return; }
            }
            if (targetConfig.colorEnabled) {
                var normT = normalizeHex(targetConfig.hex);
                if (!normT) {
                    alert("目标颜色 HEX 无效：" + targetConfig.hex + "\n请输入如 #FF3B30 的 6 位色值。");
                    return;
                }
                targetConfig.hex = normT;
                cfg.matchColor = hexToRgb(normT);
            }
        }

        if (baseConfig.enabled) {
            if (baseConfig.fontEnabled) {
                cfg.baseFont = fontTree[baseConfig.catIdx].families[baseConfig.famIdx].styles[baseConfig.wgtIdx].ps;
            }
            if (baseConfig.sizeEnabled) {
                cfg.baseSize = parseFloat(baseConfig.sizeVal);
                if (isNaN(cfg.baseSize) || cfg.baseSize <= 0) {
                    alert("底文字号无效：" + baseConfig.sizeVal);
                    return;
                }
            }
            if (baseConfig.colorEnabled) {
                var normB = normalizeHex(baseConfig.hex);
                if (!normB) {
                    alert("底字颜色 HEX 无效：" + baseConfig.hex + "\n请输入如 #FF3B30 的 6 位色值。");
                    return;
                }
                baseConfig.hex = normB;
                cfg.baseColor = hexToRgb(normB);
            }
        }

        // ==================== 批量执行（单步撤销） ====================
        var failMessages = [];
        var successCount = 0;

        function executeAll() {
            for (var n = 0; n < targetLayers.length; n++) {
                try {
                    if (applyTextStyles(targetLayers[n].id, cfg)) successCount++;
                } catch (err) {
                    failMessages.push("图层 [" + targetLayers[n].name + "]: " + err);
                }
            }
        }

        try {
            // 字符串回调经实测可访问本闭包内的局部函数与变量
            doc.suspendHistory("批量修改文本样式(Pro)", "executeAll()");
        } catch (eHist) {
            // 万一某版本不吃字符串回调，退化为直接执行（只损失单步撤销）
            executeAll();
        } finally {
            // 恢复原本的多选选中状态，出错也不丢
            try {
                if (targetLayers.length > 0) {
                    selectSingleLayerById(targetLayers[0].id);
                    for (var m = 1; m < targetLayers.length; m++) {
                        var addDesc = new ActionDescriptor();
                        var addRef = new ActionReference();
                        addRef.putIdentifier(CID("Lyr "), targetLayers[m].id);
                        addDesc.putReference(CID("null"), addRef);
                        addDesc.putEnumerated(stringIDToTypeID("selectionModifier"), stringIDToTypeID("selectionModifierType"), stringIDToTypeID("addToSelection"));
                        addDesc.putBoolean(CID("MkVs"), false);
                        executeAction(CID("slct"), addDesc, DialogModes.NO);
                    }
                }
            } catch (eRestore) {}
        }

        if (failMessages.length > 0) {
            alert("⚠️ 部分图层处理失败（成功 " + successCount + " 个）：\n" + failMessages.join("\n"));
        }
    } catch (eGlobal) {
        alert("脚本执行异常: " + (eGlobal.message ? eGlobal.message : eGlobal) + (eGlobal.line ? "\n(第 " + eGlobal.line + " 行)" : ""));
    }
})();

